1	import type pg from "pg";
2	import { getConfig } from "../config";
3	import { parseQuery, compileAst, echoAst, buildFilterClauses, parseDateParam, baseFiltersOnly } from "./index";
4	import { classifyLeaf } from "./leaf";
5	import type { SearchFilters } from "./filters";
6	import { decodeCursor, encodeCursor, hashFilters } from "./cursor";
7	
8	export type SearchParams = {
9	  q?: string | undefined;
10	  from?: string | undefined;
11	  to?: string | undefined;
12	  source?: string[] | undefined;
13	  lang?: string[] | undefined;
14	  sentiment?: string[] | undefined;
15	  topic?: string[] | undefined;
16	  limit?: number | undefined;
17	  cursor?: string | undefined;
18	  includeTotal?: boolean | undefined;
19	};
20	
21	function multi(v: string | string[] | null | undefined): string[] | undefined {
22	  if (!v) return undefined;
23	  const arr = Array.isArray(v) ? v : v.split(",");
24	  const cleaned = arr.map((s) => s.trim()).filter(Boolean);
25	  return cleaned.length ? cleaned : undefined;
26	}
27	
28	export function filtersFromParams(sp: SearchParams): SearchFilters {
29	  const filters: SearchFilters = {};
30	  const from = parseDateParam(sp.from, "from");
31	  const to = parseDateParam(sp.to, "to");
32	  if (from) filters.from = from;
33	  if (to) filters.to = to;
34	  const sources = multi(sp.source);
35	  if (sources) filters.sources = sources;
36	  const languages = multi(sp.lang);
37	  if (languages) filters.languages = languages;
38	  const sentiments = multi(sp.sentiment);
39	  if (sentiments) filters.sentiments = sentiments;
40	  const topics = multi(sp.topic);
41	  if (topics) filters.topics = topics;
42	  return filters;
43	}
44	
45	export async function runSearch(db: pg.Pool | pg.PoolClient, sp: SearchParams) {
46	  const config = getConfig();
47	  const q = sp.q ?? "";
48	  const parsed = parseQuery(q);
49	  if (!parsed.ok) {
50	    return {
51	      status: 400 as const,
52	      body: {
53	        error: parsed.error,
54	        parsed: null,
55	      },
56	    };
57	  }
58	
59	  const filters = filtersFromParams(sp);
60	  const filterHash = hashFilters(
61	    JSON.stringify({
62	      q,
63	      from: sp.from ?? null,
64	      to: sp.to ?? null,
65	      source: sp.source ?? null,
66	      lang: sp.lang ?? null,
67	      sentiment: sp.sentiment ?? null,
68	      topic: sp.topic ?? null,
69	    }),
70	  );
71	
72	  let limit = sp.limit ?? 20;
73	  if (limit < 1) limit = 1;
74	  if (limit > 100) limit = 100;
75	
76	  const compiled = compileAst(parsed.ast, 1);
77	  const afterText = buildFilterClauses(filters, compiled.params.length + 1);
78	  const whereParts: string[] = [];
79	  if (compiled.sql) whereParts.push(`(${compiled.sql})`);
80	  whereParts.push(...afterText.clauses);
81	
82	  let cursorClause = "";
83	  const params: unknown[] = [...compiled.params, ...afterText.params];
84	  let nextIdx = afterText.nextIndex;
85	
86	  if (sp.cursor) {
87	    const cur = decodeCursor(sp.cursor, config.cursorSecret);
88	    if (!cur || cur.filterHash !== filterHash) {
89	      return {
90	        status: 400 as const,
91	        body: { error: { code: "bad_cursor", message: "Cursor does not match current filters", position: 0 } },
92	      };
93	    }
94	    cursorClause = ` AND (a.published_at, a.id) < ($${nextIdx}::timestamptz, $${nextIdx + 1}::bigint)`;
95	    params.push(cur.publishedAt, cur.id);
96	    nextIdx += 2;
97	  }
98	
99	  const where = whereParts.length ? `WHERE ${whereParts.join(" AND ")}${cursorClause}` : `WHERE true${cursorClause}`;
100	
101	  // matched_in is a set of sides; evaluated only for returned rows (outer SELECT).
102	  const sideParts: string[] = [];
103	  if (compiled.originalSql) {
104	    sideParts.push(
105	      `CASE WHEN (${compiled.originalSql}) THEN 'original'::text END`,
106	    );
107	  }
108	  if (compiled.translationSql) {
109	    sideParts.push(
110	      `CASE WHEN (${compiled.translationSql}) THEN 'translation'::text END`,
111	    );
112	  }
113	  if (compiled.summarySql) {
114	    sideParts.push(
115	      `CASE WHEN (${compiled.summarySql}) THEN 'summary'::text END`,
116	    );
117	  }
118	  const matchedInExpr =
119	    sideParts.length > 0
120	      ? `array_remove(ARRAY[${sideParts.join(", ")}], NULL)`
121	      : `ARRAY['original']::text[]`;
122	
123	  const listSql = `
124	    SELECT a.id, a.external_id, a.source, a.language, a.published_at,
125	           a.headline, left(a.body, 600) AS body_excerpt, a.flags, a.ingested_at,
126	           a.version,
127	           tr.headline_en,
128	           left(tr.body_en, 600) AS body_excerpt_en,
129	           (${matchedInExpr}) AS matched_in
130	      FROM articles a
131	      LEFT JOIN article_translations tr
132	        ON tr.article_id = a.id
133	       AND tr.article_version = a.version
134	       AND tr.superseded_at IS NULL
135	       AND tr.target_lang = 'en'
136	      ${where}
137	     ORDER BY a.published_at DESC, a.id DESC
138	     LIMIT $${nextIdx}
139	  `;
140	  params.push(limit + 1);
141	
142	  const started = performance.now();
143	  let rows: pg.QueryResultRow[];
144	  try {
145	    const res = await db.query(listSql, params);
146	    rows = res.rows;
147	  } catch (err) {
148	    const msg = err instanceof Error ? err.message : String(err);
149	    if (msg.includes("statement timeout") || msg.includes("canceling statement")) {
150	      return {
151	        status: 503 as const,
152	        body: { error: { code: "timeout", message: "That search took too long. Try narrowing the date range or removing a wildcard." } },
153	      };
154	    }
155	    throw err;
156	  }
157	  const queryMs = performance.now() - started;
158	
159	  const hasMore = rows.length > limit;
160	  const page = hasMore ? rows.slice(0, limit) : rows;
161	  const ids = page.map((r) => r.id as string);
162	
163	  const derived =
164	    ids.length === 0
165	      ? { rows: [] as pg.QueryResultRow[] }
166	      : await db.query(
167	          `SELECT * FROM derived_values WHERE article_id = ANY($1::bigint[]) AND is_current`,
168	          [ids],
169	        );
170	  const jobs =
171	    ids.length === 0
172	      ? { rows: [] as pg.QueryResultRow[] }
173	      : await db.query(`SELECT * FROM enrichment_jobs WHERE article_id = ANY($1::bigint[])`, [ids]);
174	
175	  const derivedBy = new Map<string, pg.QueryResultRow[]>();
176	  for (const d of derived.rows) {
177	    const k = String(d.article_id);
178	    const list = derivedBy.get(k) ?? [];
179	    list.push(d);
180	    derivedBy.set(k, list);
181	  }
182	  const jobsBy = new Map<string, pg.QueryResultRow[]>();
183	  for (const j of jobs.rows) {
184	    const k = String(j.article_id);
185	    const list = jobsBy.get(k) ?? [];
186	    list.push(j);
187	    jobsBy.set(k, list);
188	  }
189	
190	  const articles = page.map((r) => {
191	    const rawMatched = r.matched_in;
192	    let matchedIn: string[];
193	    if (Array.isArray(rawMatched)) {
194	      matchedIn = rawMatched.map(String).filter(Boolean);
195	    } else if (typeof rawMatched === "string" && rawMatched.length) {
196	      // legacy single-side string
197	      matchedIn = rawMatched === "both" ? ["original", "translation"] : [rawMatched];
198	    } else {
199	      matchedIn = ["original"];
200	    }
201	    return {
202	      id: String(r.id),
203	      external_id: r.external_id,
204	      source: r.source,
205	      language: r.language,
206	      published_at: r.published_at,
207	      headline: r.headline,
208	      body_excerpt: r.body_excerpt,
209	      body_excerpt_en: (r.body_excerpt_en as string | null) ?? null,
210	      flags: r.flags,
211	      ingested_at: r.ingested_at,
212	      version: Number(r.version ?? 1),
213	      headline_en: (r.headline_en as string | null) ?? null,
214	      matched_in: matchedIn,
215	      derived: derivedBy.get(String(r.id)) ?? [],
216	      jobs: jobsBy.get(String(r.id)) ?? [],
217	    };
218	  });
219	
220	  let nextCursor: string | null = null;
221	  if (hasMore) {
222	    const last = page[page.length - 1]!;
223	    nextCursor = encodeCursor(
224	      {
225	        publishedAt: new Date(last.published_at as string).toISOString(),
226	        id: String(last.id),
227	        filterHash,
228	      },
229	      config.cursorSecret,
230	    );
231	  }
232	
233	  const coverage = await computeCoverage(db, filters, q, parsed.ast !== null);
234	  const translationCoverage = await computeTranslationCoverage(db, filters);
235	  const summaryMissing = await computeSummaryMissing(db, filters);
236	
237	  const trgmFlag = await db.query<{ value: string }>(
238	    `SELECT value FROM system_flags WHERE key = 'trgm_index'`,
239	  );
240	  const trgmIndex = trgmFlag.rows[0]?.value === "on";
241	
242	  let total: number | undefined;
243	  if (sp.includeTotal) {
244	    const countParams = [...compiled.params, ...afterText.params];
245	    const countWhere = whereParts.length ? `WHERE ${whereParts.join(" AND ")}` : "WHERE true";
246	    const c = await db.query<{ n: string }>(
247	      `SELECT count(*)::text AS n FROM articles a ${countWhere}`,
248	      countParams,
249	    );
250	    total = Number(c.rows[0]?.n ?? 0);
251	  }
252	
253	  const hasUnquotedLatin = hasUnquotedLatinTerm(parsed.ast);
254	  const echoNotes: string[] = [];
255	  if (/\p{Script=Arabic}|\p{Script=Han}|\p{Script=Hiragana}|\p{Script=Katakana}/u.test(q)) {
256	    echoNotes.push(
257	      "Non-Latin terms are matched as text fragments in the original and in the translation.",
258	    );
259	  }
260	  if (/\bNOT\b/i.test(q)) {
261	    echoNotes.push(
262	      "NOT terms exclude articles by their original text only, including other forms of the word.",
263	    );
264	  }
265	  if (hasUnquotedLatin) {
266	    echoNotes.push(
267	      "Words without quotes also match other forms and parts of words. Use quotes for an exact match.",
268	    );
269	  }
270	  if (!trgmIndex) {
271	    echoNotes.push("Partial-word matching is running slowly right now.");
272	  }
273	  if (summaryMissing > 0) {
274	    echoNotes.push(
275	      `${summaryMissing} articles in this selection have no summary yet, so English terms in summaries may miss them.`,
276	    );
277	  }
278	
279	  return {
280	    status: 200 as const,
281	    body: {
282	      articles,
283	      next_cursor: nextCursor,
284	      parsed: echoAst(parsed.ast),
285	      echo_notes: echoNotes,
286	      coverage,
287	      translation_coverage: translationCoverage,
288	      summary_missing: summaryMissing,
289	      trgm_index: trgmIndex,
290	      search_kind: compiled.broadestKind,
291	      ...(total !== undefined ? { total } : {}),
292	      resolved_range: {
293	        from: filters.from?.toISOString() ?? null,
294	        to: filters.to?.toISOString() ?? null,
295	      },
296	    },
297	    timing: queryMs,
298	  };
299	}
300	
301	function hasUnquotedLatinTerm(ast: import("./parse").AstNode | null): boolean {
302	  if (!ast) return false;
303	  if (ast.type === "term") {
304	    if (ast.phrase || ast.wildcard) return false;
305	    return classifyLeaf(ast.value) === "stem_sub" || classifyLeaf(ast.value) === "short_stem";
306	  }
307	  if (ast.type === "and" || ast.type === "or" || ast.type === "and_not") {
308	    return hasUnquotedLatinTerm(ast.left) || hasUnquotedLatinTerm(ast.right);
309	  }
310	  return false;
311	}
312	
313	async function computeSummaryMissing(
314	  db: pg.Pool | pg.PoolClient,
315	  filters: SearchFilters,
316	): Promise<number> {
317	  const { clauses, params } = buildFilterClauses(filters, 1);
318	  const where = clauses.length ? `WHERE ${clauses.join(" AND ")}` : "WHERE true";
319	  const res = await db.query<{ n: string }>(
320	    `SELECT count(*)::text AS n FROM articles a
321	      ${where}
322	      AND NOT EXISTS (
323	        SELECT 1 FROM derived_values dv
324	         WHERE dv.article_id = a.id AND dv.field = 'summary' AND dv.is_current
325	      )`,
326	    params,
327	  );
328	  return Number(res.rows[0]?.n ?? 0);
329	}
330	
331	export type TranslationCoverage = {
332	  foreign: number;
333	  translated: number;
334	  queued: number;
335	  paused: number;
336	  failed: number;
337	  older_not_scheduled: number;
338	  selection: number;
339	};
340	
341	async function computeTranslationCoverage(
342	  db: pg.Pool | pg.PoolClient,
343	  filters: SearchFilters,
344	): Promise<TranslationCoverage> {
345	  const { clauses, params, nextIndex: _n } = buildFilterClauses(filters, 1);
346	  const where = clauses.length ? `WHERE ${clauses.join(" AND ")}` : "WHERE true";
347	  const res = await db.query<{
348	    foreign: string;
349	    translated: string;
350	    queued: string;
351	    paused: string;
352	    failed: string;
353	    older_not_scheduled: string;
354	    selection: string;
355	  }>(
356	    `WITH sel AS (
357	       SELECT a.id, a.version, a.language
358	         FROM articles a
359	         ${where}
360	     ),
361	     foreign_sel AS (
362	       SELECT s.* FROM sel s
363	        WHERE lower(split_part(replace(coalesce(s.language,''), '_', '-'), '-', 1))
364	              NOT IN ('en', 'eng')
365	           OR coalesce(trim(s.language), '') = ''
366	     )
367	     SELECT
368	       (SELECT count(*)::text FROM sel) AS selection,
369	       (SELECT count(*)::text FROM foreign_sel) AS foreign,
370	       (SELECT count(*)::text FROM foreign_sel f
371	         JOIN article_translations t ON t.article_id = f.id AND t.article_version = f.version
372	          AND t.superseded_at IS NULL) AS translated,
373	       (SELECT count(*)::text FROM foreign_sel f
374	         JOIN enrichment_jobs j ON j.article_id = f.id AND j.article_version = f.version
375	          AND j.part = 'translation'
376	          AND j.state IN ('queued','running','failed_retryable')) AS queued,
377	       (SELECT count(*)::text FROM foreign_sel f
