import type pg from "pg";
import { getConfig } from "../config";
import { parseQuery, compileAst, echoAst, buildFilterClauses, parseDateParam, baseFiltersOnly } from "./index";
import { classifyLeaf } from "./leaf";
import type { SearchFilters } from "./filters";
import { decodeCursor, encodeCursor, hashFilters } from "./cursor";

export type SearchParams = {
  q?: string | undefined;
  from?: string | undefined;
  to?: string | undefined;
  source?: string[] | undefined;
  lang?: string[] | undefined;
  sentiment?: string[] | undefined;
  topic?: string[] | undefined;
  limit?: number | undefined;
  cursor?: string | undefined;
  includeTotal?: boolean | undefined;
};

function multi(v: string | string[] | null | undefined): string[] | undefined {
  if (!v) return undefined;
  const arr = Array.isArray(v) ? v : v.split(",");
  const cleaned = arr.map((s) => s.trim()).filter(Boolean);
  return cleaned.length ? cleaned : undefined;
}

export function filtersFromParams(sp: SearchParams): SearchFilters {
  const filters: SearchFilters = {};
  const from = parseDateParam(sp.from, "from");
  const to = parseDateParam(sp.to, "to");
  if (from) filters.from = from;
  if (to) filters.to = to;
  const sources = multi(sp.source);
  if (sources) filters.sources = sources;
  const languages = multi(sp.lang);
  if (languages) filters.languages = languages;
  const sentiments = multi(sp.sentiment);
  if (sentiments) filters.sentiments = sentiments;
  const topics = multi(sp.topic);
  if (topics) filters.topics = topics;
  return filters;
}

export async function runSearch(db: pg.Pool | pg.PoolClient, sp: SearchParams) {
  const config = getConfig();
  const q = sp.q ?? "";
  const parsed = parseQuery(q);
  if (!parsed.ok) {
    return {
      status: 400 as const,
      body: {
        error: parsed.error,
        parsed: null,
      },
    };
  }

  const filters = filtersFromParams(sp);
  const filterHash = hashFilters(
    JSON.stringify({
      q,
      from: sp.from ?? null,
      to: sp.to ?? null,
      source: sp.source ?? null,
      lang: sp.lang ?? null,
      sentiment: sp.sentiment ?? null,
      topic: sp.topic ?? null,
    }),
  );

  let limit = sp.limit ?? 20;
  if (limit < 1) limit = 1;
  if (limit > 100) limit = 100;

  const compiled = compileAst(parsed.ast, 1);
  const afterText = buildFilterClauses(filters, compiled.params.length + 1);
  const whereParts: string[] = [];
  if (compiled.sql) whereParts.push(`(${compiled.sql})`);
  whereParts.push(...afterText.clauses);

  let cursorClause = "";
  const params: unknown[] = [...compiled.params, ...afterText.params];
  let nextIdx = afterText.nextIndex;

  if (sp.cursor) {
    const cur = decodeCursor(sp.cursor, config.cursorSecret);
    if (!cur || cur.filterHash !== filterHash) {
      return {
        status: 400 as const,
        body: { error: { code: "bad_cursor", message: "Cursor does not match current filters", position: 0 } },
      };
    }
    cursorClause = ` AND (a.published_at, a.id) < ($${nextIdx}::timestamptz, $${nextIdx + 1}::bigint)`;
    params.push(cur.publishedAt, cur.id);
    nextIdx += 2;
  }

  const where = whereParts.length ? `WHERE ${whereParts.join(" AND ")}${cursorClause}` : `WHERE true${cursorClause}`;

  // matched_in is a set of sides; evaluated only for returned rows (outer SELECT).
  const sideParts: string[] = [];
  if (compiled.originalSql) {
    sideParts.push(
      `CASE WHEN (${compiled.originalSql}) THEN 'original'::text END`,
    );
  }
  if (compiled.translationSql) {
    sideParts.push(
      `CASE WHEN (${compiled.translationSql}) THEN 'translation'::text END`,
    );
  }
  if (compiled.summarySql) {
    sideParts.push(
      `CASE WHEN (${compiled.summarySql}) THEN 'summary'::text END`,
    );
  }
  const matchedInExpr =
    sideParts.length > 0
      ? `array_remove(ARRAY[${sideParts.join(", ")}], NULL)`
      : `ARRAY['original']::text[]`;

  const listSql = `
    SELECT a.id, a.external_id, a.source, a.language, a.published_at,
           a.headline, left(a.body, 600) AS body_excerpt, a.flags, a.ingested_at,
           a.version,
           tr.headline_en,
           left(tr.body_en, 600) AS body_excerpt_en,
           (${matchedInExpr}) AS matched_in
      FROM articles a
      LEFT JOIN article_translations tr
        ON tr.article_id = a.id
       AND tr.article_version = a.version
       AND tr.superseded_at IS NULL
       AND tr.target_lang = 'en'
      ${where}
     ORDER BY a.published_at DESC, a.id DESC
     LIMIT $${nextIdx}
  `;
  params.push(limit + 1);

  const started = performance.now();
  let rows: pg.QueryResultRow[];
  try {
    const res = await db.query(listSql, params);
    rows = res.rows;
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    if (msg.includes("statement timeout") || msg.includes("canceling statement")) {
      return {
        status: 503 as const,
        body: { error: { code: "timeout", message: "That search took too long. Try narrowing the date range or removing a wildcard." } },
      };
    }
    throw err;
  }
  const queryMs = performance.now() - started;

  const hasMore = rows.length > limit;
  const page = hasMore ? rows.slice(0, limit) : rows;
  const ids = page.map((r) => r.id as string);

  const derived =
    ids.length === 0
      ? { rows: [] as pg.QueryResultRow[] }
      : await db.query(
          `SELECT * FROM derived_values WHERE article_id = ANY($1::bigint[]) AND is_current`,
          [ids],
        );
  const jobs =
    ids.length === 0
      ? { rows: [] as pg.QueryResultRow[] }
      : await db.query(`SELECT * FROM enrichment_jobs WHERE article_id = ANY($1::bigint[])`, [ids]);

  const derivedBy = new Map<string, pg.QueryResultRow[]>();
  for (const d of derived.rows) {
    const k = String(d.article_id);
    const list = derivedBy.get(k) ?? [];
    list.push(d);
    derivedBy.set(k, list);
  }
  const jobsBy = new Map<string, pg.QueryResultRow[]>();
  for (const j of jobs.rows) {
    const k = String(j.article_id);
    const list = jobsBy.get(k) ?? [];
    list.push(j);
    jobsBy.set(k, list);
  }

  const articles = page.map((r) => {
    const rawMatched = r.matched_in;
    let matchedIn: string[];
    if (Array.isArray(rawMatched)) {
      matchedIn = rawMatched.map(String).filter(Boolean);
    } else if (typeof rawMatched === "string" && rawMatched.length) {
      // legacy single-side string
      matchedIn = rawMatched === "both" ? ["original", "translation"] : [rawMatched];
    } else {
      matchedIn = ["original"];
    }
    return {
      id: String(r.id),
      external_id: r.external_id,
      source: r.source,
      language: r.language,
      published_at: r.published_at,
      headline: r.headline,
      body_excerpt: r.body_excerpt,
      body_excerpt_en: (r.body_excerpt_en as string | null) ?? null,
      flags: r.flags,
      ingested_at: r.ingested_at,
      version: Number(r.version ?? 1),
      headline_en: (r.headline_en as string | null) ?? null,
      matched_in: matchedIn,
      derived: derivedBy.get(String(r.id)) ?? [],
      jobs: jobsBy.get(String(r.id)) ?? [],
    };
  });

  let nextCursor: string | null = null;
  if (hasMore) {
    const last = page[page.length - 1]!;
    nextCursor = encodeCursor(
      {
        publishedAt: new Date(last.published_at as string).toISOString(),
        id: String(last.id),
        filterHash,
      },
      config.cursorSecret,
    );
  }

  const coverage = await computeCoverage(db, filters, q, parsed.ast !== null);
  const translationCoverage = await computeTranslationCoverage(db, filters);
  const summaryMissing = await computeSummaryMissing(db, filters);

  const trgmFlag = await db.query<{ value: string }>(
    `SELECT value FROM system_flags WHERE key = 'trgm_index'`,
  );
  const trgmIndex = trgmFlag.rows[0]?.value === "on";

  let total: number | undefined;
  if (sp.includeTotal) {
    const countParams = [...compiled.params, ...afterText.params];
    const countWhere = whereParts.length ? `WHERE ${whereParts.join(" AND ")}` : "WHERE true";
    const c = await db.query<{ n: string }>(
      `SELECT count(*)::text AS n FROM articles a ${countWhere}`,
      countParams,
    );
    total = Number(c.rows[0]?.n ?? 0);
  }

  const hasUnquotedLatin = hasUnquotedLatinTerm(parsed.ast);
  const echoNotes: string[] = [];
  if (/\p{Script=Arabic}|\p{Script=Han}|\p{Script=Hiragana}|\p{Script=Katakana}/u.test(q)) {
    echoNotes.push(
      "Non-Latin terms are matched as text fragments in the original and in the translation.",
    );
  }
  if (/\bNOT\b/i.test(q)) {
    echoNotes.push(
      "NOT terms exclude articles by their original text only, including other forms of the word.",
    );
  }
  if (hasUnquotedLatin) {
    echoNotes.push(
      "Words without quotes also match other forms and parts of words. Use quotes for an exact match.",
    );
  }
  if (!trgmIndex) {
    echoNotes.push("Partial-word matching is running slowly right now.");
  }
  if (summaryMissing > 0) {
    echoNotes.push(
      `${summaryMissing} articles in this selection have no summary yet, so English terms in summaries may miss them.`,
    );
  }

  return {
    status: 200 as const,
    body: {
      articles,
      next_cursor: nextCursor,
      parsed: echoAst(parsed.ast),
      echo_notes: echoNotes,
      coverage,
      translation_coverage: translationCoverage,
      summary_missing: summaryMissing,
      trgm_index: trgmIndex,
      search_kind: compiled.broadestKind,
      ...(total !== undefined ? { total } : {}),
      resolved_range: {
        from: filters.from?.toISOString() ?? null,
        to: filters.to?.toISOString() ?? null,
      },
    },
    timing: queryMs,
  };
}

function hasUnquotedLatinTerm(ast: import("./parse").AstNode | null): boolean {
  if (!ast) return false;
  if (ast.type === "term") {
    if (ast.phrase || ast.wildcard) return false;
    return classifyLeaf(ast.value) === "stem_sub" || classifyLeaf(ast.value) === "short_stem";
  }
  if (ast.type === "and" || ast.type === "or" || ast.type === "and_not") {
    return hasUnquotedLatinTerm(ast.left) || hasUnquotedLatinTerm(ast.right);
  }
  return false;
}

async function computeSummaryMissing(
  db: pg.Pool | pg.PoolClient,
  filters: SearchFilters,
): Promise<number> {
  const { clauses, params } = buildFilterClauses(filters, 1);
  const where = clauses.length ? `WHERE ${clauses.join(" AND ")}` : "WHERE true";
  const res = await db.query<{ n: string }>(
    `SELECT count(*)::text AS n FROM articles a
      ${where}
      AND NOT EXISTS (
        SELECT 1 FROM derived_values dv
         WHERE dv.article_id = a.id AND dv.field = 'summary' AND dv.is_current
      )`,
    params,
  );
  return Number(res.rows[0]?.n ?? 0);
}

export type TranslationCoverage = {
  foreign: number;
  translated: number;
  queued: number;
  paused: number;
  failed: number;
  older_not_scheduled: number;
  selection: number;
};

async function computeTranslationCoverage(
  db: pg.Pool | pg.PoolClient,
  filters: SearchFilters,
): Promise<TranslationCoverage> {
  const { clauses, params, nextIndex: _n } = buildFilterClauses(filters, 1);
  const where = clauses.length ? `WHERE ${clauses.join(" AND ")}` : "WHERE true";
  const res = await db.query<{
    foreign: string;
    translated: string;
    queued: string;
    paused: string;
    failed: string;
    older_not_scheduled: string;
    selection: string;
  }>(
    `WITH sel AS (
       SELECT a.id, a.version, a.language
         FROM articles a
         ${where}
     ),
     foreign_sel AS (
       SELECT s.* FROM sel s
        WHERE lower(split_part(replace(coalesce(s.language,''), '_', '-'), '-', 1))
              NOT IN ('en', 'eng')
           OR coalesce(trim(s.language), '') = ''
     )
     SELECT
       (SELECT count(*)::text FROM sel) AS selection,
       (SELECT count(*)::text FROM foreign_sel) AS foreign,
       (SELECT count(*)::text FROM foreign_sel f
         JOIN article_translations t ON t.article_id = f.id AND t.article_version = f.version
          AND t.superseded_at IS NULL) AS translated,
       (SELECT count(*)::text FROM foreign_sel f
         JOIN enrichment_jobs j ON j.article_id = f.id AND j.article_version = f.version
          AND j.part = 'translation'
          AND j.state IN ('queued','running','failed_retryable')) AS queued,
       (SELECT count(*)::text FROM foreign_sel f
         JOIN enrichment_jobs j ON j.article_id = f.id AND j.article_version = f.version
          AND j.part = 'translation' AND j.state = 'deferred_budget') AS paused,
       (SELECT count(*)::text FROM foreign_sel f
         JOIN enrichment_jobs j ON j.article_id = f.id AND j.article_version = f.version
          AND j.part = 'translation' AND j.state = 'dead') AS failed,
       (SELECT count(*)::text FROM foreign_sel f
         WHERE NOT EXISTS (
           SELECT 1 FROM enrichment_jobs j
            WHERE j.article_id = f.id AND j.part = 'translation'
         )) AS older_not_scheduled`,
    params,
  );
  const r = res.rows[0];
  return {
    selection: Number(r?.selection ?? 0),
    foreign: Number(r?.foreign ?? 0),
    translated: Number(r?.translated ?? 0),
    queued: Number(r?.queued ?? 0),
    paused: Number(r?.paused ?? 0),
    failed: Number(r?.failed ?? 0),
    older_not_scheduled: Number(r?.older_not_scheduled ?? 0),
  };
}

async function computeCoverage(
  db: pg.Pool | pg.PoolClient,
  filters: SearchFilters,
  _q: string,
  _hasText: boolean,
) {
  const base = baseFiltersOnly(filters);
  const baseBuild = buildFilterClauses(base, 1);
  const baseWhere = baseBuild.clauses.length
    ? `WHERE ${baseBuild.clauses.join(" AND ")}`
    : "WHERE true";

  const baseCount = await db.query<{ n: string }>(
    `SELECT count(*)::text AS n FROM articles a ${baseWhere}`,
    baseBuild.params,
  );

  const fullBuild = buildFilterClauses(filters, 1);
  // articles in scope = after all filters except we want text-agnostic for "in scope" as matching filters
  // Spec: articles_in_scope after filters including text; for coverage line use enriched counts on corpus
  const all = await db.query<{
    total: string;
    with_sent: string;
    with_topic: string;
    max_pub: string | null;
    max_ing: string | null;
  }>(
    `SELECT
       (SELECT count(*)::text FROM articles) AS total,
       (SELECT count(DISTINCT article_id)::text FROM derived_values WHERE field='sentiment' AND is_current) AS with_sent,
       (SELECT count(DISTINCT article_id)::text FROM derived_values WHERE field='topic' AND is_current) AS with_topic,
       (SELECT max(published_at)::text FROM articles) AS max_pub,
       (SELECT max(ingested_at)::text FROM articles) AS max_ing`,
  );

  const row = all.rows[0]!;
  const articlesMatchingBase = Number(baseCount.rows[0]?.n ?? 0);

  let excludedByNotEnriched = 0;
  if (filters.sentiments?.includes("not_enriched") || filters.topics?.includes("not_enriched")) {
    // informational
  }
  if (
    (filters.sentiments && filters.sentiments.some((s) => s !== "not_enriched")) ||
    (filters.topics && filters.topics.some((t) => t !== "not_enriched"))
  ) {
    const withoutDerived = buildFilterClauses(base, 1);
    const withDerived = fullBuild;
    // approximate: base minus those with matching derived — skip heavy calc; use difference of counts
    const c1 = await db.query<{ n: string }>(
      `SELECT count(*)::text AS n FROM articles a ${
        withoutDerived.clauses.length ? `WHERE ${withoutDerived.clauses.join(" AND ")}` : "WHERE true"
      }`,
      withoutDerived.params,
    );
    // for excluded: articles matching base+text but missing enrichment filter — UI uses this when filter applied
    excludedByNotEnriched = Math.max(0, Number(c1.rows[0]?.n ?? 0) - articlesMatchingBase);
    void withDerived;
  }

  return {
    articles_matching_base_filters: articlesMatchingBase,
    articles_in_scope: Number(row.total),
    enriched_sentiment: Number(row.with_sent),
    enriched_topics: Number(row.with_topic),
    excluded_by_filter_not_enriched: excludedByNotEnriched,
    watermark: {
      published_at: row.max_pub,
      ingested_at: row.max_ing,
    },
  };
}

