1	import { normaliseText } from "../normalise";
2	
3	/** Match modes for a single term leaf (ADR-0031, 0033, 0035). */
4	export type LeafKind =
5	  | "stem_sub"
6	  | "short_stem"
7	  | "exact"
8	  | "substring"
9	  | "phrase"
10	  | "wildcard";
11	
12	/** Postgres `english` stop words that yield an empty plainto_tsquery. */
13	const ENGLISH_STOPWORDS = new Set([
14	  "a",
15	  "about",
16	  "an",
17	  "are",
18	  "as",
19	  "at",
20	  "be",
21	  "but",
22	  "by",
23	  "for",
24	  "from",
25	  "has",
26	  "he",
27	  "in",
28	  "is",
29	  "it",
30	  "its",
31	  "of",
32	  "on",
33	  "that",
34	  "the",
35	  "to",
36	  "was",
37	  "were",
38	  "will",
39	  "with",
40	]);
41	
42	export function isEnglishStopword(term: string): boolean {
43	  return ENGLISH_STOPWORDS.has(term.toLocaleLowerCase("en-US"));
44	}
45	
46	function isNonLatin(term: string): boolean {
47	  if (/[\u0600-\u06FF\u0750-\u077F\u08A0-\u08FF\uFB50-\uFDFF\uFE70-\uFEFF]/.test(term)) {
48	    return true;
49	  }
50	  if (/[\u3040-\u30FF\u3400-\u9FFF\uF900-\uFAFF]/.test(term)) {
51	    return true;
52	  }
53	  return false;
54	}
55	
56	/**
57	 * Choose match mode by script, quoting, length (ADR-0033).
58	 * Quoted single-word phrases are exact; multi-word phrases stay phrase.
59	 */
60	export function classifyLeaf(term: string, opts?: { phrase?: boolean; wildcard?: boolean }): LeafKind {
61	  if (opts?.wildcard) return "wildcard";
62	  if (opts?.phrase) {
63	    // Single-token quoted term → exact; multi-word → phrase
64	    if (/\s/.test(term.trim())) return "phrase";
65	    return "exact";
66	  }
67	  if (isNonLatin(term)) return "substring";
68	  const norm = normaliseText(term);
69	  if (norm.length < 3) return "short_stem";
70	  return "stem_sub";
71	}
72	
73	export function escapeIlike(term: string): string {
74	  return term.replace(/\\/g, "\\\\").replace(/%/g, "\\%").replace(/_/g, "\\_");
75	}
76	
77	export function normaliseLeafTerm(term: string): string {
78	  return normaliseText(term);
79	}
80	
81	/** Exact expression text must match migration 0007 (FP-DB1). */
82	export const EXPR = {
83	  articlesFtsEn: `to_tsvector('english', a.search_text)`,
84	  articlesLangPred: `split_part(a.language, '-', 1) IN ('en', 'und')`,
85	  translationsFtsEn: `to_tsvector('english', t.search_text)`,
