402	async function computeCoverage(
403	  db: pg.Pool | pg.PoolClient,
404	  filters: SearchFilters,
405	  _q: string,
406	  _hasText: boolean,
407	) {
408	  const base = baseFiltersOnly(filters);
409	  const baseBuild = buildFilterClauses(base, 1);
410	  const baseWhere = baseBuild.clauses.length
411	    ? `WHERE ${baseBuild.clauses.join(" AND ")}`
412	    : "WHERE true";
413	
414	  const baseCount = await db.query<{ n: string }>(
415	    `SELECT count(*)::text AS n FROM articles a ${baseWhere}`,
416	    baseBuild.params,
417	  );
418	
419	  const fullBuild = buildFilterClauses(filters, 1);
420	  // articles in scope = after all filters except we want text-agnostic for "in scope" as matching filters
421	  // Spec: articles_in_scope after filters including text; for coverage line use enriched counts on corpus
422	  const all = await db.query<{
423	    total: string;
424	    with_sent: string;
425	    with_topic: string;
426	    max_pub: string | null;
427	    max_ing: string | null;
428	  }>(
429	    `SELECT
430	       (SELECT count(*)::text FROM articles) AS total,
431	       (SELECT count(DISTINCT article_id)::text FROM derived_values WHERE field='sentiment' AND is_current) AS with_sent,
432	       (SELECT count(DISTINCT article_id)::text FROM derived_values WHERE field='topic' AND is_current) AS with_topic,
433	       (SELECT max(published_at)::text FROM articles) AS max_pub,
434	       (SELECT max(ingested_at)::text FROM articles) AS max_ing`,
435	  );
436	
437	  const row = all.rows[0]!;
438	  const articlesMatchingBase = Number(baseCount.rows[0]?.n ?? 0);
439	
440	  let excludedByNotEnriched = 0;
441	  if (filters.sentiments?.includes("not_enriched") || filters.topics?.includes("not_enriched")) {
442	    // informational
443	  }
444	  if (
445	    (filters.sentiments && filters.sentiments.some((s) => s !== "not_enriched")) ||
446	    (filters.topics && filters.topics.some((t) => t !== "not_enriched"))
447	  ) {
448	    const withoutDerived = buildFilterClauses(base, 1);
449	    const withDerived = fullBuild;
450	    // approximate: base minus those with matching derived — skip heavy calc; use difference of counts
451	    const c1 = await db.query<{ n: string }>(
452	      `SELECT count(*)::text AS n FROM articles a ${
453	        withoutDerived.clauses.length ? `WHERE ${withoutDerived.clauses.join(" AND ")}` : "WHERE true"
454	      }`,
455	      withoutDerived.params,
456	    );
457	    // for excluded: articles matching base+text but missing enrichment filter — UI uses this when filter applied
458	    excludedByNotEnriched = Math.max(0, Number(c1.rows[0]?.n ?? 0) - articlesMatchingBase);
459	    void withDerived;
460	  }
461	
462	  return {
463	    articles_matching_base_filters: articlesMatchingBase,
464	    articles_in_scope: Number(row.total),
465	    enriched_sentiment: Number(row.with_sent),
466	    enriched_topics: Number(row.with_topic),
467	    excluded_by_filter_not_enriched: excludedByNotEnriched,
468	    watermark: {
469	      published_at: row.max_pub,
470	      ingested_at: row.max_ing,
471	    },
472	  };
473	}
