1	import { counter } from "../metrics";
2	import type { AstNode } from "./parse";
3	import {
4	  classifyLeaf,
5	  escapeIlike,
6	  EXPR,
7	  isEnglishStopword,
8	  normaliseLeafTerm,
9	} from "./leaf";
10	
11	const emptyStem = counter(
12	  "mss_search_empty_stem_total",
13	  "Stop-word-only terms that fell back from English stem",
14	);
15	
16	export type CompiledQuery = {
17	  sql: string | null;
18	  params: unknown[];
19	  /** Original-side-only predicate (same param indices as sql). */
20	  originalSql: string | null;
21	  /** Translation-side EXISTS predicate (same param indices as sql). */
22	  translationSql: string | null;
23	  /** Summary-side EXISTS predicate (same param indices as sql). */
24	  summarySql: string | null;
25	  /** Broadest term kind in the query for telemetry. */
26	  broadestKind: "exact" | "stem_sub" | "nonlatin_sub" | "none";
27	};
28	
29	type Side = "both" | "original" | "translation" | "summary";
30	
31	type TermMeta = {
32	  key: string;
33	  value: unknown;
34	  kind: ReturnType<typeof classifyLeaf>;
35	  /** When stem is empty (stop word), use this fallback mode. */
36	  stemEmpty: boolean;
37	};
38	
39	/**
40	 * Compile AST to a SQL boolean fragment.
41	 * Positive term leaves match original OR current translation OR current summary (ADR-0035).
42	 * The right side of `and_not` matches the original only (ADR-0027); never stem-OR summary.
43	 */
44	export function compileAst(ast: AstNode | null, startIndex = 1): CompiledQuery {
45	  if (!ast) {
46	    return {
47	      sql: null,
48	      params: [],
49	      originalSql: null,
50	      translationSql: null,
51	      summarySql: null,
52	      broadestKind: "none",
53	    };
54	  }
55	
56	  const params: unknown[] = [];
57	  let next = startIndex;
58	  const indexByKey = new Map<string, number>();
59	  const metaByNode = new WeakMap<object, TermMeta>();
60	  let broadestKind: CompiledQuery["broadestKind"] = "exact";
61	
62	  function widenKind(k: TermMeta["kind"]) {
63	    if (k === "substring") {
64	      broadestKind = "nonlatin_sub";
65	      return;
66	    }
67	    if (k === "stem_sub" || k === "short_stem") {
68	      if (broadestKind !== "nonlatin_sub") broadestKind = "stem_sub";
69	      return;
70	    }
71	    // exact / phrase / wildcard stay at exact unless already wider
72	  }
73	
74	  function paramIndex(key: string, value: unknown): number {
75	    const existing = indexByKey.get(key);
76	    if (existing !== undefined) return existing;
77	    params.push(value);
78	    const i = next;
79	    next++;
80	    indexByKey.set(key, i);
81	    return i;
82	  }
83	
84	  function termMeta(node: Extract<AstNode, { type: "term" }>): TermMeta {
85	    const cached = metaByNode.get(node);
86	    if (cached) return cached;
87	
88	    const classifyOpts: { phrase?: boolean; wildcard?: boolean } = {};
89	    if (node.phrase) classifyOpts.phrase = true;
90	    if (node.wildcard) classifyOpts.wildcard = true;
91	    const kind = classifyLeaf(node.value, classifyOpts);
92	    const norm = normaliseLeafTerm(node.value);
93	    const stemEmpty = (kind === "stem_sub" || kind === "short_stem") && isEnglishStopword(norm);
94	    if (stemEmpty) emptyStem.inc();
95	    widenKind(kind);
96	
97	    let meta: TermMeta;
98	    if (kind === "substring") {
99	      meta = { key: `sub:${norm}`, value: `%${escapeIlike(norm)}%`, kind, stemEmpty };
100	    } else if (kind === "phrase") {
101	      meta = { key: `phrase:${norm}`, value: norm, kind, stemEmpty };
102	    } else if (kind === "wildcard") {
103	      const safe = norm.replace(/[^\p{L}\p{N}]+/gu, "");
104	      meta = { key: `wild:${safe}`, value: `${safe}:*`, kind, stemEmpty };
105	    } else if (kind === "exact") {
106	      meta = { key: `exact:${norm}`, value: norm, kind, stemEmpty };
107	    } else if (kind === "stem_sub") {
108	      meta = { key: `stem_sub:${norm}`, value: norm, kind, stemEmpty };
109	    } else {
110	      meta = { key: `short_stem:${norm}`, value: norm, kind, stemEmpty };
111	    }
